 IF (SELECT relrowsecurity IS DISTINCT FROM true OR relforcerowsecurity IS DISTINCT FROM false OR pg_get_userbyid(relowner) IS DISTINCT FROM 'postgres' OR relacl::text IS DISTINCT FROM '{postgres=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres}' FROM pg_class WHERE oid='public.client_memberships'::regclass) THEN RAISE EXCEPTION 'Wave5 table security drift: client_memberships'; END IF;
 IF (SELECT jsonb_agg(jsonb_build_object('name',polname,'check',pg_get_expr(polwithcheck,polrelid),'roles',ARRAY(SELECT rolname FROM pg_roles WHERE oid=ANY(polroles) ORDER BY rolname),'using',pg_get_expr(polqual,polrelid),'command',polcmd::text,'permissive',polpermissive) ORDER BY polname) FROM pg_policy WHERE polrelid='public.client_memberships'::regclass) IS DISTINCT FROM '[{"name":"client_memberships_staff_insert","check":"(EXISTS ( SELECT 1\n   FROM staff_access s\n  WHERE (s.user_id = ( SELECT auth.uid() AS uid))))","roles":["authenticated"],"using":null,"command":"a","permissive":true},{"name":"client_memberships_staff_or_member_select","check":null,"roles":["authenticated"],"using":"((EXISTS ( SELECT 1\n   FROM staff_access s\n  WHERE (s.user_id = ( SELECT auth.uid() AS uid)))) OR (id IN ( SELECT ca.membership_id\n   FROM client_access ca\n  WHERE (ca.user_id = ( SELECT auth.uid() AS uid)))))","command":"r","permissive":true},{"name":"client_memberships_staff_update","check":"(EXISTS ( SELECT 1\n   FROM staff_access s\n  WHERE (s.user_id = ( SELECT auth.uid() AS uid))))","roles":["authenticated"],"using":"(EXISTS ( SELECT 1\n   FROM staff_access s\n  WHERE (s.user_id = ( SELECT auth.uid() AS uid))))","command":"w","permissive":true},{"name":"lifecycle_paid_access","check":"(( SELECT private.active_staff_session() AS active_staff_session) OR ( SELECT private.full_member_access() AS full_member_access))","roles":["authenticated"],"using":"(( SELECT private.active_staff_session() AS active_staff_session) OR ( SELECT private.full_member_access() AS full_member_access))","command":"*","permissive":false}]'::jsonb THEN RAISE EXCEPTION 'Wave5 original policy drift: client_memberships'; END IF;
