 p:='private.staff_has_permission(uuid,text)'::regprocedure; IF md5(pg_get_functiondef(p)) IS DISTINCT FROM 'd9a0fcfb28e77a3a27d8c3f65abd174c' THEN RAISE EXCEPTION 'Wave5 authorization dependency drift: staff_has_permission'; END IF;
 p:='private.staff_action_allowed(uuid,text,uuid)'::regprocedure; IF md5(pg_get_functiondef(p)) IS DISTINCT FROM '8a56153aee64b660f01935262b086670' THEN RAISE EXCEPTION 'Wave5 authorization dependency drift: staff_action_allowed'; END IF;
 p:='private.full_member_access()'::regprocedure; IF md5(pg_get_functiondef(p)) IS DISTINCT FROM 'e007e0c9403d511c0f687ef4e883d19d' THEN RAISE EXCEPTION 'Wave5 authorization dependency drift: full_member_access'; END IF;
 p:='private.wave4_membership_allowed(uuid,text)'::regprocedure; IF (SELECT md5(prosrc) IS DISTINCT FROM 'f461830d750a349391812a73bc57be99' OR prosecdef IS DISTINCT FROM true OR pg_get_userbyid(proowner) IS DISTINCT FROM 'postgres' OR proconfig IS DISTINCT FROM ARRAY['search_path=""']::text[] OR proacl::text IS DISTINCT FROM '{postgres=X/postgres,authenticated=X/postgres}' FROM pg_proc WHERE oid=p) THEN RAISE EXCEPTION 'Wave5 accepted boolean dependency drift'; END IF;
