DO $collision$ BEGIN IF EXISTS(SELECT FROM pg_policy WHERE polrelid='public.client_memberships'::regclass AND polname='wave5_client_memberships_scope_insert') THEN RAISE EXCEPTION 'Wave5 policy collision'; END IF; END $collision$;
