DO $collision$ BEGIN IF EXISTS(SELECT FROM pg_policy WHERE polrelid='public.client_access'::regclass AND polname='wave5_client_access_scope_select') THEN RAISE EXCEPTION 'Wave5 policy collision'; END IF; END $collision$;
DO $collision$ BEGIN IF EXISTS(SELECT FROM pg_policy WHERE polrelid='public.client_access'::regclass AND polname='wave5_client_access_scope_insert') THEN RAISE EXCEPTION 'Wave5 policy collision'; END IF; END $collision$;
DO $collision$ BEGIN IF EXISTS(SELECT FROM pg_policy WHERE polrelid='public.client_access'::regclass AND polname='wave5_client_access_scope_update') THEN RAISE EXCEPTION 'Wave5 policy collision'; END IF; END $collision$;
CREATE POLICY wave5_client_memberships_scope_select ON public.client_memberships AS RESTRICTIVE FOR SELECT TO authenticated USING (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.view',primary_contact_id)) OR id IN(SELECT ca.membership_id FROM public.client_access ca WHERE ca.user_id=auth.uid())));
CREATE POLICY wave5_client_memberships_scope_insert ON public.client_memberships AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK ((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',primary_contact_id)));
CREATE POLICY wave5_client_memberships_scope_update ON public.client_memberships AS RESTRICTIVE FOR UPDATE TO authenticated USING ((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',primary_contact_id))) WITH CHECK ((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',primary_contact_id)));
CREATE POLICY wave5_client_access_scope_select ON public.client_access AS RESTRICTIVE FOR SELECT TO authenticated USING (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.view',contact_id)) OR user_id=auth.uid()));
CREATE POLICY wave5_client_access_scope_insert ON public.client_access AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',contact_id)) AND (membership_id IS NULL OR private.wave4_membership_allowed(membership_id,'coaching.manage'))));
CREATE POLICY wave5_client_access_scope_update ON public.client_access AS RESTRICTIVE FOR UPDATE TO authenticated USING (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',contact_id)) AND (membership_id IS NULL OR private.wave4_membership_allowed(membership_id,'coaching.manage')))) WITH CHECK (((private.active_staff_session() AND private.staff_action_allowed(auth.uid(),'crm.manage',contact_id)) AND (membership_id IS NULL OR private.wave4_membership_allowed(membership_id,'coaching.manage'))));
